(function () {
  if (!globalThis.DATA) return;
  for (const row of MONSTER_REFERENCE.species) {
    const species = DATA.species[row.index];
    if (!species || species.system_entry_id !== row.system_entry_id) throw new Error('Monster reference identity mismatch');
    species.name = row.current_name;
    species.short_name = row.short_name;
    species.display_name = row.display_name;
    species.aliases = row.aliases;
  }
  for (const rule of DATA.runtime_rules?.rules || []) {
    rule.pedigree_name = DATA.species[rule.pedigree_index].display_name;
    rule.offspring_name = DATA.species[rule.offspring_index].display_name;
    rule.mate_name = rule.mate_index == null
      ? 'Any ' + DATA.families.find(family => family.id === rule.mate_family_index).display_name + '-family monster'
      : DATA.species[rule.mate_index].display_name;
  }
  DATA.metadata.names = 'Current English patch names from the public translation snapshot. Gameplay provenance is independent.';
  DATA.metadata.translation_sync = MONSTER_REFERENCE.metadata;
})();
